import json,csv,re,statistics as st,math
T=[json.loads(l) for l in open('data/judge_transcripts.jsonl')]
S={r['rating_id']:int(r['score']) for r in csv.DictReader(open('data/scores.csv'))}
def calc(f):
    d={}
    for t in T: d.setdefault(t['response_id'],{})[t['displayed_label']]=f(t)
    x=[v['atlas-7']-v['nova-3'] for v in d.values()]
    m=st.mean(x);se=st.stdev(x)/math.sqrt(len(x));return m,se,m/se,st.stdev(x)
print(calc(lambda t:int(re.findall(r'FINAL SCORE:\s*(\d+)',t['judge_output'])[0])))
print(calc(lambda t:S[t['rating_id']]))
# order effect
d={}
for t in T:
    d.setdefault(t['response_id'],{})[t['displayed_label']]=(int(re.findall(r'SCORE:\s*(\d+)',t['judge_output'])[0]),t['session'])
a=[v['atlas-7'][0]-v['nova-3'][0] for v in d.values() if v['atlas-7'][1]==1]
b=[v['atlas-7'][0]-v['nova-3'][0] for v in d.values() if v['atlas-7'][1]==2]
print(len(a),st.mean(a),len(b),st.mean(b))

